if(kind==='newPet'){let pet={id:id(),name:data.name.trim(),species:data.species,breed:data.breed,sex:data.sex,birth:data.birth,sterilized:data.sterilized==='yes'};db.pets.push(pet);db.active=pet.id;save();closeModal();tab='home';render();toast('На одну счастливую лапку больше! 🐾');return}
if(kind==='profile'){Object.assign(p(),{name:data.name.trim(),species:data.species,breed:data.breed,sex:data.sex,birth:data.birth,sterilized:data.sterilized==='yes',chip:data.chip,details:data.details,birthAccuracy:data.birthAccuracy||'approx'});save();closeModal();render();toast('Профиль обновлён');return}
if(kind==='heatStart'){let open=mine('events').find(x=>x.type==='heat'&&!x.end);if(open){toast('Сначала отметьте завершение предыдущей течки');return}add('events',{type:'heat',date:data.date,detail:data.detail});return}
if(kind==='heatEnd'){let open=mine('events').find(x=>x.type==='heat'&&!x.end);if(!open)return;if(days(open.date,data.date)<0){toast('Дата окончания раньше начала');return}open.end=data.date;save();closeModal();render();toast('Окончание отмечено');return}
if(kind==='measure'){const x=Number(data.weight);if(!(x>0&&x<=250))return toast('Укажите корректный вес');add('weights',{weight:x,date:data.date});return}
if(kind==='food'||kind==='editFood'){
if(!data.name?.trim())return toast('Введите название корма');
let url=String(data.sourceUrl||'').trim();
if(url){try{const u=new URL(url);if(!['http:','https:'].includes(u.protocol))throw Error('scheme');url=u.href}catch{return toast('Проверьте ссылку: нужен адрес http(s)')}}
const entry={name:data.name.trim(),brand:data.brand?.trim()||'',sourceUrl:url,format:data.format,targetSpecies:data.targetSpecies,complete:data.complete,stage:data.stage,ingredients:data.ingredients?.trim()||'',analysis:data.analysis?.trim()||''};
if(kind==='editFood'){const old=(db.foods||[]).find(x=>x.id===draft.editFoodId&&x.petId===p().id);if(!old)return toast('Корм не найден');Object.assign(old,entry);save();closeModal();render();toast('Карточка обновлена 💜');return}
return add('foods',{...entry,date:TODAY()});
}
if(kind==='foodReaction'){const food=(db.foods||[]).find(x=>x.id===data.foodId&&x.petId===p().id);if(!data.date||data.date>TODAY())return toast('Укажите дату не позднее сегодняшней');return add('foodReactions',{date:data.date,foodId:food?.id||'',foodName:food?.name||data.foodName?.trim()||'',appetite:data.appetite,digestion:data.digestion,notes:data.notes?.trim()||''})}
if(kind==='shopping')return add('shopping',{name:data.name.trim(),done:false});
if(kind==='event')return add('events',{type:'event',name:data.name.trim(),detail:data.detail,date:data.date});
if(kind==='visit'){add('visits',{name:data.name,detail:data.detail,date:data.date});add('notes',{name:'Итоги визита: '+(data.name||'ветеринар'),detail:data.detail,date:data.date});return}
