async function importData(){let f=document.getElementById('importFile')?.files[0];if(!f)return toast('Выберите файл');try{let j=JSON.parse(await f.text());if(!Array.isArray(j.pets)||!Array.isArray(j.events)||!Array.isArray(j.notes)||!Array.isArray(j.weights)||!Array.isArray(j.vaccines)||!Array.isArray(j.shopping)||!Array.isArray(j.foods)||!Array.isArray(j.visits))throw Error('Файл не похож на резервную копию Purrfect');if(!confirm('Заменить все данные в этом браузере?'))return;db={...structuredClone(initial),...j};save();closeModal();tab='home';render();toast('Данные восстановлены')}catch(e){toast('Ошибка импорта: '+e.message)}}

function extractFoodLabelSections(input){
const raw=String(input||'').replace(/\r/g,'').trim();
const compact=raw.replace(/\s+/g,' ').trim();
const headings=[
{type:'ingredients',re:/(?:^|[\s.;])(?:ИНГРЕДИЕНТЫ|СОСТАВ|INGREDIENTS|COMPOSITION)\s*[:：–—-]?/giu},
{type:'additives',re:/(?:^|[\s.;])(?:ПИЩЕВЫЕ\s+ДОБАВКИ|ДОБАВКИ|ADDITIVES(?:\s+PER\s+KG)?)\s*[:：–—-]?/giu},
{type:'analysis',re:/(?:^|[\s.;])(?:СОДЕРЖАНИЕ\s+ПИТАТЕЛЬНЫХ\s+ВЕЩЕСТВ|АНАЛИТИЧЕСКИЕ\s+КОМПОНЕНТЫ|АНАЛИТИЧЕСКИЙ\s+СОСТАВ|ANALYTICAL\s+CONSTITUENTS|ANALYTICAL\s+COMPONENTS)\s*[:：–—-]?/giu}
];
const hits=headings.flatMap(h=>[...compact.matchAll(h.re)].map(m=>({type:h.type,start:m.index,end:m.index+m[0].length}))).sort((a,b)=>a.start-b.start);
const result={ingredients:'',analysis:'',hasIngredients:false,hasAnalysis:false,pairs:0,warning:''};
for(let i=0;i<hits.length;i++){
const h=hits[i];const next=hits.find(x=>x.start>=h.end);
const content=compact.slice(h.end,next?.start??compact.length).replace(/^[\s:;.,—–-]+|[\s:;.,—–-]+$/g,'').trim();
if(h.type==='ingredients'&&content&&!result.hasIngredients){result.ingredients=content;result.hasIngredients=true}
if(h.type==='analysis'&&content&&!result.hasAnalysis){result.analysis=content;result.hasAnalysis=true}
}
const names='бел(?:ок|ка|ки|ков)|протеин|жир(?:ы|а|ов)?|зол[аы]|клетчатк[аи]|влажност[ьи]|влаг[аи]|омега[ -]?[36]|кальци[йя]|фосфор|protein|fat|ash|fibre|fiber|moisture|omega[ -]?[36]';
const pairs=[...compact.matchAll(new RegExp('(?:'+names+')\\s*[:=—–-]?\\s*\\d{1,3}(?:[.,]\\d{1,3})?\\s*%','giu'))].map(m=>m[0]);
result.pairs=pairs.length;
if(!result.hasAnalysis&&pairs.length){result.analysis=pairs.join(' · ');result.hasAnalysis=true}

result.ingredients=result.ingredients.slice(0,4000);
result.analysis=result.analysis.slice(0,2000);
return result;
}
function cleanFoodIngredients(raw){
let text=String(raw||'').replace(/\s+/g,' ').trim();
// OCR often confuses Cyrillic С/О/Т/А/В with visually similar Latin C/O/T/A/B.
// Match these variants ONLY at the beginning of the field, not in ingredient names.
const heading='(?:[СC][ОO][СC][ТT][АA][ВB]|ИНГРЕДИЕНТЫ|INGREDIENTS)';
text=text.replace(new RegExp('^(?:(?:RHE|RНE|THE)\\s+)?'+heading+'\\s*[:：–—-]?\\s*','iu'),'');
text=text.split(/(?:^|[\s.;])(?:ПИЩЕВЫЕ\s+ДОБАВКИ|ДОБАВКИ|ADDITIVES|СОДЕРЖАНИЕ\s+ПИТАТЕЛЬНЫХ\s+ВЕЩЕСТВ|АНАЛИТИЧЕСКИЕ\s+КОМПОНЕНТЫ)\s*[:：–—-]?/i)[0];
return text.replace(/^[\s:;.,—–-]+|[\s:;.,—–-]+$/g,'').trim();
}
function cleanCurrentFoodIngredients(){
const form=document.querySelector('.modalOverlay [data-form="editFood"],.modalOverlay [data-form="food"]');
const input=form?.elements.namedItem('ingredients');if(!input)return;
const old=input.value,next=cleanFoodIngredients(old);
if(!old.trim())return toast('Поле ингредиентов пустое');
if(next===old.trim())return toast('Лишние заголовки не найдены');
if(!next)return toast('Не удалось уверенно отделить ингредиенты; текст оставлен без изменений');
input.value=next;toast('Заголовки и добавки убраны из поля. Проверьте текст и сохраните.');
}
function applyFoodImportText(){
const field=document.getElementById('foodImportText'),form=field?.closest('form');if(!form)return;
const raw=field.value.trim();if(!raw)return toast('Сначала вставьте или распознайте текст');
const parsed=extractFoodLabelSections(raw),an=form.elements.namedItem('analysis'),ing=form.elements.namedItem('ingredients');
const status=document.getElementById('foodOcrStatus');
if(parsed.hasAnalysis&&an)an.value=parsed.analysis;
if(parsed.hasIngredients&&ing)ing.value=cleanFoodIngredients(parsed.ingredients);
const missing=[];
if(!parsed.hasIngredients)missing.push('состав');
if(!parsed.hasAnalysis)missing.push('аналитические компоненты');
if(status)status.textContent=missing.length?'Перенесены только найденные разделы. Не найдены: '+missing.join(', ')+'. Остальные поля не изменены.':'Оба раздела перенесены. Проверьте каждую цифру и ингредиенты.';
toast(missing.length?'Импорт неполный — проверьте недостающие поля':'Разделы перенесены — проверьте поля');
}
function loadFoodOcrScript(){
if(window.Tesseract?.recognize)return Promise.resolve(window.Tesseract);
if(window.foodOcrLoading)return window.foodOcrLoading;
window.foodOcrLoading=new Promise((resolve,reject)=>{
const sc=document.createElement('script');
sc.src='https://cdn.jsdelivr.net/npm/tesseract.js@5.1.1/dist/tesseract.min.js';
sc.onload=()=>window.Tesseract?.recognize?resolve(window.Tesseract):reject(Error('Библиотека недоступна'));
sc.onerror=()=>reject(Error('Не удалось скачать библиотеку'));
document.head.appendChild(sc);
}).catch(e=>{window.foodOcrLoading=null;throw e});
return window.foodOcrLoading;
}
async function recognizeFoodLabel(){
const input=document.getElementById('foodLabelPhoto'),status=document.getElementById('foodOcrStatus'),btn=document.querySelector('[data-act="recognizeFood"]');
const file=input?.files?.[0];if(!file)return toast('Выберите фото этикетки');
if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024)return toast('Нужно фото JPG, PNG или WebP до 10 МБ');
if(btn)btn.disabled=true;if(status)status.textContent='Загрузка распознавания. Нужен интернет…';
try{
const ocr=await loadFoodOcrScript();
const result=await ocr.recognize(file,'rus+eng',{logger:m=>{if(status&&m.status==='recognizing text')status.textContent='Распознавание: '+Math.round((m.progress||0)*100)+'%'}});
const recognized=String(result.data?.text||'').trim(),output=document.getElementById('foodImportText');
if(!output)return;if(!recognized){if(status)status.textContent='Текст не найден. Сделайте более чёткий снимок.';return}
output.value=(output.value?output.value.trim()+'\n':'')+recognized.slice(0,Math.max(0,12000-output.value.length));
if(status)status.textContent='Готово! Перенесите данные в поля и проверьте их. Фотография не сохранена.';
}catch(err){if(status)status.textContent='Распознавание недоступно: '+(err.message||'ошибка')+'. Вставьте текст вручную.'}
finally{if(btn)btn.disabled=false}
}
document.addEventListener('submit',e=>{if(e.target.id==='onboardForm'){e.preventDefault();submitForm('newPet',collect(e.target));return}if(e.target.matches('[data-form]')){e.preventDefault();submitForm(e.target.dataset.form,collect(e.target))}});
document.addEventListener('click',e=>{let t=e.target.closest('[data-tab],[data-act]');if(!t)return;let newTab=t.dataset.tab;if(newTab){tab=newTab;closeModal();render();window.scrollTo(0,0);return}let action=t.dataset.act;if(action==='close')return closeModal();
if(action.startsWith('editFood:')){draft.editFoodId=action.slice('editFood:'.length);openModal('editFood');return}
if(action==='recognizeFood'){recognizeFoodLabel();return}
if(action==='applyFoodText'){applyFoodImportText();return}
if(action==='cleanFoodIngredients'){cleanCurrentFoodIngredients();return}
if(action.startsWith('careFilter:')){const next=action.slice('careFilter:'.length);if(['all','food','note','weight'].includes(next)){careFilter=next;render()}return}
if(action.startsWith('foodDetail:')||action.startsWith('reactionDetail:')||action.startsWith('linkedFood:')){const [kind,ident]=action.split(':');draft.detailId=ident;openModal(kind==='reactionDetail'?'reactionDetail':'foodDetail');return}if(action.startsWith('switchPet:')){db.active=action.split(':')[1];save();closeModal();tab='home';render();return}if(action.startsWith('delete')||action.startsWith('toggleShop:')){let [cmd,ident]=action.split(':');let map={deleteEvent:'events',deleteWeight:'weights',deleteNote:'notes',deleteVaccine:'vaccines',deleteFood:'foods',deleteReaction:'foodReactions',deleteShop:'shopping'};if(cmd==='toggleShop'){let v=db.shopping.find(x=>x.id===ident);if(v)v.done=!v.done}else if(map[cmd]){if(!confirm('Удалить эту запись?'))return;if(cmd==='deleteNote'){const target=db.notes.find(x=>x.id===ident);if(target){db.noteTombstones=Array.isArray(db.noteTombstones)?db.noteTombstones:[];if(!db.noteTombstones.some(x=>x.id===ident))db.noteTombstones.push({id:ident,petId:target.petId,deletedAt:new Date().toISOString()})}}db[map[cmd]]=db[map[cmd]].filter(x=>x.id!==ident)}save();render();return}
if(action.startsWith('theme:')){localStorage.setItem(THEME_KEY,action.split(':')[1]==='dark'?'dark':'light');applyTheme();render();toast('Оформление изменено 💜');return}if(action==='calendar'){tab='calendar';render();return}if(action==='calendarPrev'||action==='calendarNext'){calendarMonth+=action==='calendarNext'?1:-1;if(calendarMonth<0){calendarMonth=11;calendarYear--}if(calendarMonth>11){calendarMonth=0;calendarYear++}render();return}if(action.startsWith('calendarDay:')){selectedCalendarDate=action.split(':')[1];render();return}if(action==='calendarAdd'){openModal('event');let f=document.querySelector('.modal [name=date]');if(f)f.value=selectedCalendarDate;return}if(action==='goDiary'){closeModal();tab='diary';render();return}if(action==='export')return download();if(action==='family'){openModal('family');return}if(action==='doImport')return importData();if(action==='copyVet'){let s=draft.vet||'';navigator.clipboard?.writeText(s).then(()=>toast('Памятка скопирована')).catch(()=>{let a=document.createElement('textarea');a.value=s;document.body.appendChild(a);a.select();document.execCommand('copy');a.remove();toast('Памятка скопирована')});return}openModal(action)});
document.addEventListener('change',async e=>{if(e.target.id!=='petPhotoInput')return;const f=e.target.files?.[0];if(!f)return;if(f.size>12*1024*1024){toast('Выберите фотографию до 12 МБ');return}try{const img=await createImageBitmap(f);const size=320;const c=document.createElement('canvas');c.width=size;c.height=size;const ctx=c.getContext('2d');const scale=Math.max(size/img.width,size/img.height);const w=img.width*scale,h=img.height*scale;ctx.drawImage(img,(size-w)/2,(size-h)/2,w,h);img.close?.();const photo=c.toDataURL('image/jpeg',.78);p().photo=photo;save();closeModal();render();toast('Фото питомца сохранено 🐾')}catch(err){toast('Не удалось загрузить фотографию')}});
window.purrfectApplyCloud=(remote)=>{if(!remote||!Array.isArray(remote.pets))return;db={...structuredClone(initial),...remote,foodReactions:Array.isArray(remote.foodReactions)?remote.foodReactions:[],noteTombstones:Array.isArray(remote.noteTombstones)?remote.noteTombstones:[]};localStorage.setItem(KEY,JSON.stringify(db));if(!db.pets.find(x=>x.id===db.active))db.active=db.pets[0]?.id||null;closeModal();render();toast('Общие данные обновлены ☁️')};window.purrfectLocalData=()=>structuredClone(db);render();if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>{});
